--
-- Дамп данных таблицы `news`
--

INSERT INTO `news` (`id`, `title`, `text`, `picture`, `category_id`, `user_id`) VALUES
(1, 'Quantum Computing Leap: Physicists Achieve 1,000-Qubit Room-Temperature Processor', 'An international consortium of quantum physicists and computer scientists has announced a landmark breakthrough in quantum information architecture. Researchers successfully demonstrated a 1,024-qubit quantum processor operating with sustained coherence near ambient temperature using diamond nitrogen-vacancy (NV) centers and photonic interconnects.\n\nThe new quantum error-correction protocol reduced hardware noise by 94%, paving the way for molecular structure modeling in drug discovery, room-temperature superconductor synthesis, and cryptographic resilience analysis.\n\n«We have crossed the threshold from cryogenic laboratory experiments to practical quantum advantage,» stated the project lead at the Global Quantum Physics Symposium in Geneva. Commercial deployments for supercomputing clusters are slated for next quarter.', , 5, 1),
(2, 'Multimodal AI Agents: Autonomous Systems Architect Software from Scratch', 'Leading artificial intelligence research laboratories have unveiled the next generation of reasoning-first multimodal models (System 2 Thinking). The new autonomous agents move beyond snippet generation to designing microservice architectures, writing test suites, provisioning databases, and self-healing regression bugs in real time.\n\nOn the industry-standard SWE-bench benchmark, the autonomous agent successfully resolved 88.6% of real-world GitHub issues without human intervention, establishing a historic world record.\n\nEngineers note that the discipline is evolving rapidly: developers are shifting focus from repetitive boilerplate syntax toward high-level conceptual modeling, system design, and safety boundaries.', , 1, 1),
(3, '2-Nanometer Silicon Unveiled: Next-Gen Processors Feature 120 TOPS NPUs', 'At the annual semiconductor technology summit, leading chipmakers announced the commercial tape-out of 2nm GAAFET (Gate-All-Around) processors designed for next-generation mobile and edge computing devices.\n\nThe new architecture delivers a 35% gain in energy efficiency while packing a dedicated Neural Processing Unit (NPU) capable of 120 TOPS. This enables local execution of heavy multimodal language models with billions of parameters directly on smartphones without transmitting data to remote cloud servers.\n\nThe first flagship consumer devices powered by the new silicon platform are scheduled to arrive on retail shelves this autumn.', , 2, 1),
(4, 'Global Cybersecurity Operation Dismantles 3-Million-Device IoT Botnet', 'Cybersecurity agencies and international law enforcement have neutralized the command-and-control infrastructure of one of history\'s largest botnets.\n\nThe botnet compromised IoT hardware, smart home gateways, and edge routers to launch massive volumetric DDoS attacks peaking at 4.8 Terabits per second against financial clearinghouses and energy grids. The coordinated sweep disabled server nodes across 12 countries and seized decryption keys that will allow thousands of affected organizations to recover encrypted systems.\n\nSecurity teams strongly urge network administrators to update border gateway router firmware and disable unauthenticated remote management ports.', , 3, 1),
(5, 'Photoreal Engine 6: Real-Time Path Tracing and Neural Physics Simulation', 'Game developers and graphics engineers have pulled back the curtain on Photoreal Engine 6, obliterating the distinction between pre-rendered CGI cinema and real-time interactive gameplay.\n\nKey innovations include dynamic full path tracing running at 120 frames per second on mainstream GPUs, neural physics simulations that calculate stress fractures procedurally, and streaming support for seamless open worlds spanning thousands of square kilometers without loading screens.\n\nTop esports titles and AAA studios have already pledged adoption of the engine, with interactive developer preview kits available for immediate download.', , 4, 1),
(6, 'Europa Mission: Deep-Space Probe Transmits Radar Sonar of Subsurface Ocean', 'An autonomous deep-space exploration probe has successfully completed its gravitational slingshot maneuver and established a stable orbit around Jupiter\'s moon, Europa. High-frequency ice-penetrating radar confirmed the existence of a global liquid water ocean extending over 100 kilometers beneath the crust.\n\nSpectrometric analysis of water vapor plumes erupting through ice fissures revealed significant concentrations of carbon, methane, and complex prebiotic organic molecules. Scientists are now preparing Phase 2: a thermal-drill lander engineered to melt through the ice shell and sample the subsurface ocean for potential microbial signatures.', , 5, 1);

